{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four category models, lower Adam learning rate to 5e-4 and dropout to 0.08 together: smaller updates may stabilize optimization while reduced dropout preserves context signal in short histories. Existing checkpoint metadata and predictor loading remain compatible. Preserve all other settings, masked-item loss, backbone, seeds and training limits.",
      "edits": [
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.1\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.08\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"7e-4\"))",
          "replace": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"5e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly set shared learning rate to 5e-4 and dropout to 0.08 for the four independent BERT4Rec category models."
}
